import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { restore } from "@tigrisdata/agent-kit";
import { S3Client, GetObjectCommand } from "@aws-sdk/client-s3";

async function main() {
  const snapshotId = readFileSync("snapshot_id.txt", "utf8").trim();
  const expected = readFileSync("expected_sha256.txt", "utf8").trim().toLowerCase();

  console.log(`Restoring snapshot ${snapshotId} to validation-fork...`);
  const { data, error } = await restore("archive-bucket", snapshotId, {
    forkName: "validation-fork",
  });
  if (error || !data) {
    throw error ?? new Error("restore returned no data");
  }
  const bucket = data.bucket;
  console.log(`Restored to bucket: ${bucket}`);

  if (!bucket.startsWith("validation-fork")) {
    throw new Error(`Restored bucket name ${bucket} does not start with validation-fork`);
  }

  const s3 = new S3Client({
    region: "REDACTED",
    endpoint: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  console.log(`Downloading manifest.json from ${bucket}...`);
  const obj = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: "manifest.json" }));
  if (!obj.Body) {
    throw new Error("S3 GetObject returned no body");
  }

  const bytes = Buffer.from(await obj.Body.transformToByteArray());
  const sha256 = createHash("sha256").update(bytes).digest("hex");

  console.log(`Computed SHA256: ${sha256}`);
  console.log(`Expected SHA256: ${expected}`);

  const result = {
    bucket,
    sha256,
    expected_sha256: expected,
    sha256_match: sha256 === expected,
  };

  writeFileSync("result.json", JSON.stringify(result, null, 2));
  console.log("RESTORE_VALIDATE_OK", JSON.stringify(result));
}

main().catch((err) => {
  console.error("Validation failed:", err);
  process.exit(1);
});

import { createBucket } from "@tigrisdata/storage";

async function main() {
  while (true) {
    console.log("Attempting to create archive-bucket...");
    const res = await createBucket("archive-bucket", { enableSnapshot: true });
    if (res.error) {
      console.log("Failed:", res.error.message);
      if (res.error.message.includes("recently deleted") || res.error.message.includes("not available")) {
        console.log("Waiting 5 seconds before retrying...");
        await new Promise(r => setTimeout(r, 5000));
        continue;
      }
      process.exit(1);
    }
    console.log("Successfully created archive-bucket with snapshots enabled!");
    break;
  }
}

main();

